    health: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description El proceso está vivo. */
            200: {
                headers: {
                    /** @description Identificador de correlación de la petición: el recibido si es válido, o uno nuevo. */
                    "X-Correlation-Id": string;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @enum {string} */
                        status: "ok";
                    };
                };
            };
        };
    };
    ready: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Lista para recibir tráfico. */
            200: {
                headers: {
                    /** @description Identificador de correlación de la petición: el recibido si es válido, o uno nuevo. */
                    "X-Correlation-Id": string;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @enum {string} */
                        status: "ready";
                        checks: {
                            /** @enum {string} */
                            database: "ok" | "fail";
                            /** @enum {string} */
                            migrations: "ok" | "pending" | "skipped" | "fail";
                        };
                    };
                };
            };
            /** @description No lista: la base no responde o hay migraciones pendientes o sin verificar. */
            503: {
                headers: {
                    /** @description Identificador de correlación de la petición: el recibido si es válido, o uno nuevo. */
                    "X-Correlation-Id": string;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @enum {string} */
                        status: "not_ready";
                        checks: {
                            /** @enum {string} */
                            database: "ok" | "fail";
                            /** @enum {string} */
                            migrations: "ok" | "pending" | "skipped" | "fail";
                        };
                    };
                };
            };
        };
    };
